_SECONDS_PER_UNIT = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
_PATTERN = re.compile(
    r'^(?:(?P<d>\d+)d)?'
    r'(?:(?P<h>\d+)h)?'
    r'(?:(?P<m>\d+)m)?'
    r'(?:(?P<s>\d+)s)?$'
)


def parse_duration(s):
    """Return the number of seconds represented by a duration string.

    Accepts strings such as '1h30m', '45s', '2h5s', and '1d2h'.  Units are
    d, h, m and s; each unit may appear at most once and in that order, and
    each amount is a non-negative integer.  Surrounding whitespace is allowed.
    """
    if not isinstance(s, str):
        raise ValueError('duration must be a string')

    s = s.strip()
    match = _PATTERN.fullmatch(s)
    if match is None:
        raise ValueError('invalid duration')

    groups = match.groupdict()
    if all(value is None for value in groups.values()):
        raise ValueError('invalid duration')

    total = 0
    for unit, seconds_per_unit in _SECONDS_PER_UNIT.items():
        amount = groups[unit]
        if amount is not None:
            total += int(amount) * seconds_per_unit
    return total
